import{_ as n,C as l,o as d,c as h,j as t,a,E as s,w as o,ao as r}from"./chunks/framework.ChMYfHUZ.js";const v=JSON.parse('{"title":"OCP hysteresis","description":"","frontmatter":{},"headers":[],"relativePath":"manuals/user_guide/ocp_hysteresis.md","filePath":"manuals/user_guide/ocp_hysteresis.md","lastUpdated":null}'),c={name:"manuals/user_guide/ocp_hysteresis.md"};function p(u,e,f,y,g,m){const i=l("CitationPreview");return d(),h("div",null,[e[5]||(e[5]=t("h1",{id:"ocp_hysteresis",tabindex:"-1"},[a("OCP hysteresis "),t("a",{class:"header-anchor",href:"#ocp_hysteresis","aria-label":'Permalink to "OCP hysteresis {#ocp_hysteresis}"'},"​")],-1)),t("p",null,[e[2]||(e[2]=a("The open-circuit potential of many electrode materials, graphite among them, is not the same after lithiation and after delithiation: after a charge a cell rests at a higher voltage than after a discharge to the same state of charge. BattMo models this with the one-state hysteresis model of PyBaMM [",-1)),s(i,null,{default:o(()=>[...e[0]||(e[0]=[t("a",{id:"sulzer2021-cite-1"},null,-1),t("a",{href:"/BattMo.jl/previews/PR200/extras/refs#sulzer2021"},"12",-1)])]),_:1}),e[3]||(e[3]=a('] ("one-state hysteresis", after [',-1)),s(i,null,{default:o(()=>[...e[1]||(e[1]=[t("a",{id:"axen2022-cite-1"},null,-1),t("a",{href:"/BattMo.jl/previews/PR200/extras/refs#axen2022"},"13",-1)])]),_:1}),e[4]||(e[4]=a("]), for each electrode whose active material gives two OCP branches.",-1))]),e[6]||(e[6]=r(`<h2 id="Model" tabindex="-1">Model <a class="header-anchor" href="#Model" aria-label="Permalink to &quot;Model {#Model}&quot;">​</a></h2><p>The open-circuit potential of the electrode is a blend of its lithiation and delithiation branches, weighted by a hysteresis state <code>h</code> in [-1, 1] in each electrode cell:</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>U = (1 + h) / 2 * U_delith(theta_s, T) + (1 - h) / 2 * U_lith(theta_s, T)</span></span>
<span class="line"><span>dh/dt = gamma * r * (1 - sign(r) * h) / 2</span></span></code></pre></div><p>Here <code>theta_s</code> is the surface stoichiometry, <code>r = i_vol / (F * c_max * eps_s)</code> the rate of change of the stoichiometry by the interfacial current density <code>i_vol</code> (positive on delithiation), and <code>gamma</code> the decay rate: <code>gamma_delith</code> on delithiation, <code>gamma_lith</code> on lithiation, each a constant or a function of the surface stoichiometry. <code>h = 1</code> is the delithiation branch, <code>h = -1</code> the lithiation branch.</p><ul><li><p>At rest <code>h</code> does not change: the electrode stays on the branch it came from.</p></li><li><p>After a reversal, the distance to the new branch falls as <code>exp(-gamma * |dtheta| / 2)</code> with the change of stoichiometry <code>dtheta</code>, not with time.</p></li><li><p>The entropy change, if used, is added to the blended OCP as to the single OCP.</p></li></ul><p>BattMo integrates the law with the implicit Euler step of the simulation, in each electrode cell, with <code>dtheta</code> the change of the cell&#39;s mean particle stoichiometry over the step. By the particle mass balance this equals <code>r * dt</code>. Each step is a convex combination of the previous <code>h</code> and the branch of the current direction, so <code>h</code> stays in [-1, 1] for any time step.</p><h2 id="Input" tabindex="-1">Input <a class="header-anchor" href="#Input" aria-label="Permalink to &quot;Input {#Input}&quot;">​</a></h2><p>The model setting switches the model on:</p><div class="language-json vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">json</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;ModelSettings&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: { </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;OCPHysteresis&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;OneState&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> }</span></span></code></pre></div><p>An electrode then has hysteresis if its <code>ActiveMaterial</code> gives both branches. The two branches and the two decay rates take the forms of <code>OpenCircuitPotential</code>: a constant, a table of the stoichiometry, an expression of <code>c</code>, <code>T</code>, <code>refT</code> and <code>cmax</code>, or a Julia function with these arguments.</p><table tabindex="0"><thead><tr><th style="text-align:left;">Key (ActiveMaterial)</th><th style="text-align:left;">Meaning</th></tr></thead><tbody><tr><td style="text-align:left;"><code>OpenCircuitPotentialLithiation</code></td><td style="text-align:left;">Lithiation branch of the OCP [V]</td></tr><tr><td style="text-align:left;"><code>OpenCircuitPotentialDelithiation</code></td><td style="text-align:left;">Delithiation branch of the OCP [V]</td></tr><tr><td style="text-align:left;"><code>HysteresisDecayRateLithiation</code></td><td style="text-align:left;">Decay rate on lithiation [-]</td></tr><tr><td style="text-align:left;"><code>HysteresisDecayRateDelithiation</code></td><td style="text-align:left;">Decay rate on delithiation [-]</td></tr></tbody></table><p><code>OpenCircuitPotential</code> stays required. With hysteresis it is used only by tools that need an equilibrium OCP, such as the equilibrium calibration.</p><p>The initial hysteresis state of each electrode is part of the cycling protocol, as the initial state of charge, and is 0, the mean of the branches, if not given:</p><table tabindex="0"><thead><tr><th style="text-align:left;">Key (CyclingProtocol)</th><th style="text-align:left;">Meaning</th></tr></thead><tbody><tr><td style="text-align:left;"><code>InitialHysteresisStateNegativeElectrode</code></td><td style="text-align:left;"><code>h</code> of the negative electrode at the start, in [-1, 1]</td></tr><tr><td style="text-align:left;"><code>InitialHysteresisStatePositiveElectrode</code></td><td style="text-align:left;"><code>h</code> of the positive electrode at the start, in [-1, 1]</td></tr></tbody></table><p>The initial electrode potentials are those of the blended OCP at this state. A simulation started from a stored state continues with the hysteresis state of that state.</p><p>The model needs the full solid diffusion model (<code>TransportInSolid = &quot;FullDiffusion&quot;</code>), and can be combined with the SEI model. BPX parameter sets with OCP hysteresis are converted as described in <a href="/BattMo.jl/previews/PR200/manuals/user_guide/bpx#bpx_functions">BPX parameter sets</a>.</p><h2 id="Output" tabindex="-1">Output <a class="header-anchor" href="#Output" aria-label="Permalink to &quot;Output {#Output}&quot;">​</a></h2><p>The hysteresis state of each electrode cell is a state variable, <code>NegativeElectrodeActiveMaterialHysteresisState</code> and <code>PositiveElectrodeActiveMaterialHysteresisState</code>; <code>...OpenCircuitPotential</code> is the blended OCP. The voltage breakdown evaluates the average OCV on the branches at the hysteresis state.</p>`,18))])}const x=n(c,[["render",p]]);export{v as __pageData,x as default};
